function file(
  id: string,
  name: string,
  language: string,
  extra: Partial<GeneratedFile>,
): GeneratedFile {
  return {
    id,
    name,
    path: `${workspace}/${name}`,
    language,
    operation: "create",
    state: "ready",
    digest: id.padEnd(64, "0").replace(/[^0-9a-f]/g, "a"),
    ...extra,
  };
}
function change(path: string): NonNullable<Item["changes"]>[number] {
  return { path, kind: { type: "add" }, diff: "" };
}

