/**
 * The artifact calls: local sharing, the library, saving and pop-out, answered
 * in memory. `artifactShare=link` starts every HTML artifact shared by local
 * link. Registered as `artifacts` in fixtures/index.ts.
 */
export const artifactsFixture: FixtureDomain = {
  params: {
    previewTransport: "data: inline opaque-origin document; default: blob",
    artifactShare: "link",
    artifactSlides: "1: one synthetic HTML slide deck (default: absent)",
    blankArtifactDelay: "delay the actual fixture create/read result in ms",
  },
  bridge: ({ params, state, emit, origin }) => {
    if (params.get("artifactSlides") === "1" && !state.conversations.some((value) => value.id === "c-artifact-slides"))
      state.conversations = [htmlSlideConversation(origin), ...state.conversations];
    const blankFiles = new Map<string, BlankArtifactDocument>();
    const pendingBlank = new Map<string, Promise<CreatedBlankArtifact>>();
    const revision = async (content: string) => [...new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(content)))].map(byte => byte.toString(16).padStart(2, "0")).join("");
    const waitBlank = () => new Promise<void>(resolve => setTimeout(resolve, Math.min(30_000, Math.max(0, Number(params.get("blankArtifactDelay")) || 0))));
    const createBlank = async (input: CreateBlankArtifactInput): Promise<CreatedBlankArtifact> => {
      const existing = state.conversations.find(c => c.id === input.requestId);
      if (existing?.blankArtifact) {
        const document = blankFiles.get(existing.blankArtifact.id)!;
        return structuredClone({conversation: existing, document});
      }
      if (!artifactOutputKinds.includes(input.kind)) throw new Error("Unknown artifact type");
      const content = blankArtifactInitialContent(input.kind), now = Date.now();
      const artifact = {id: crypto.randomUUID(), kind: input.kind, name: input.kind === "dashboard" ? "Dashboard" : "Untitled", file: blankArtifactFiles[input.kind], createdAt: now};
      const document = {conversationId: input.requestId, artifact, content, revision: await revision(content), writable: true};
      const conversation: Conversation = {id: input.requestId, title: input.name, mode: "chat", providerId: input.providerId, model: input.model, pinned: false, archived: false, createdAt: now, updatedAt: now, turns: [], blankArtifact: artifact};
      blankFiles.set(artifact.id, document);state.conversations = [conversation, ...state.conversations];emit({type: "conversation", conversation: structuredClone(conversation)});
      return structuredClone({conversation, document});
    };
    const shares = new Map<string, ArtifactShareInfo>();
    const notes: ArtifactNotes = {};
    const linked = params.get("artifactShare") === "link";
    const info = (identity: string): ArtifactShareInfo =>
      shares.get(identity) ??
      (linked
        ? { identity, visibility: "link", showInList: true, url: localLink }
        : { identity, visibility: "private", showInList: true });
    const library = (next: ArtifactLibraryState) => {
      state.artifactLibrary = next;
      return structuredClone(next);
    };
    return {
      createBlankArtifact: async input => {
        let pending = pendingBlank.get(input.requestId);
        if (!pending) {pending = waitBlank().then(() => createBlank(input));pendingBlank.set(input.requestId, pending);}
        try {return await pending;} finally {if (pendingBlank.get(input.requestId) === pending) pendingBlank.delete(input.requestId);}
      },
      readBlankArtifact: async input => {
        await waitBlank();
        const c = state.conversations.find(c => c.id === input.conversationId), value = blankFiles.get(input.artifactId);
        if (!value || c?.blankArtifact?.id !== input.artifactId) throw new Error("This artifact is not available in this account.");
        return structuredClone(value);
      },
      saveBlankArtifact: async input => {
        const c = state.conversations.find(c => c.id === input.conversationId), value = blankFiles.get(input.artifactId);
        if (!value || c?.blankArtifact?.id !== input.artifactId) return {status: "missing"};
        if (c.turns.some(turn => turn.status === "inProgress")) return {status: "denied", reason: "generating"};
        const nextRevision = await revision(input.content);
        if (value.revision !== input.expectedRevision) return {status: "conflict", currentRevision: value.revision};
        const document = {...value, content: input.content, revision: nextRevision};blankFiles.set(input.artifactId, document);c.updatedAt = Date.now();emit({type: "conversation", conversation: structuredClone(c)});
        return {status: "saved", document: structuredClone(document)};
      },
      syncArtifactShare: async (input) => info(input.identity),
      setArtifactShare: async (input, patch) => {
        const current = info(input.identity);
        const visibility = patch.visibility ?? current.visibility;
        const next: ArtifactShareInfo = {
          identity: input.identity,
          visibility,
          showInList: patch.showInList ?? current.showInList,
          ...(visibility === "link" ? { url: localLink } : {}),
        };
        shares.set(input.identity, next);
        state.artifactShares = [...shares.values()];
        emit({ type: "artifact-shares", shares: state.artifactShares });
        return next;
      },
      artifactNotes: async () => structuredClone(notes),
      updateArtifactNote: async (key, patch) => {
        const note: ArtifactNote = { ...notes[key] };
        if (patch.conversationId) note.conversationId = patch.conversationId;
        if (patch.name !== undefined)
          Object.assign(note, { name: patch.name, renamedAt: Date.now() });
        if (patch.viewed) note.viewedAt = Date.now();
        if (patch.comments) note.comments = patch.comments;
        notes[key] = note;
        return structuredClone(note);
      },
      importArtifactNotes: async (incoming) => {
        for (const [key, note] of Object.entries(incoming))
          notes[key] = { ...note, ...notes[key] };
        return structuredClone(notes);
      },
      duplicateArtifact: async (input) => {
        const artifact = {
          libraryId: crypto.randomUUID(),
          name: `${input.name} copy`,
          language: input.language,
          content: input.content,
          originConversationId: input.originConversationId,
          createdAt: Date.now(),
        };
        const next = library({
          ...state.artifactLibrary,
          copies: [...state.artifactLibrary.copies, artifact],
        });
        return { artifact, library: next };
      },
      deleteArtifactCopy: async (libraryId) =>
        library({
          ...state.artifactLibrary,
          copies: state.artifactLibrary.copies.filter(
            (copy) => copy.libraryId !== libraryId,
          ),
        }),
      pinArtifact: async (identity, pinned) =>
        library({
          ...state.artifactLibrary,
          pinned: pinned
            ? [identity, ...state.artifactLibrary.pinned]
            : state.artifactLibrary.pinned.filter(
                (value) => value !== identity,
              ),
        }),
      saveArtifact: async (name) => `/Users/fixture/Downloads/${name}`,
      saveGeneratedFile: async (_digest, name) =>
        `/Users/fixture/Downloads/${name}`,
      popOutArtifact: async () => {},
    };
  },
};
